'use strict';
const portal=document.body.dataset.portal;
const STORE='roki-workspace-demo-v1';
const TODAY='2026-11-18';
const users=[
{id:'r-issue',name:'Somchai K.',role:'Issue',portal:'roki',email:'issuer@roki.example'},
{id:'r-check',name:'Jaruphan P.',role:'Check',portal:'roki',email:'checker@roki.example'},
{id:'r-approve',name:'Purchasing manager',role:'Approve',portal:'roki',email:'approver@roki.example'},
{id:'s1-issue',name:'Nattapong S.',role:'Issue',portal:'supplier',supplier:'s1',email:'issuer@thai-precision.example'},
{id:'s1-approve',name:'Anong P.',role:'Approve',portal:'supplier',supplier:'s1',email:'approver@thai-precision.example'},
{id:'s2-issue',name:'Pim S.',role:'Issue',portal:'supplier',supplier:'s2',email:'issuer@siam-filter.example'},
{id:'s2-approve',name:'Somsak T.',role:'Approve',portal:'supplier',supplier:'s2',email:'approver@siam-filter.example'}];
const suppliers=[{id:'s1',name:'Thai Precision Co., Ltd.',code:'TP-001'},{id:'s2',name:'Siam Filter Industries',code:'SF-002'}];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=v=>Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const timestamp=()=>new Date().toLocaleString('en-GB',{timeZone:'Asia/Bangkok',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' ICT';
const uid=prefix=>prefix+'-'+crypto.randomUUID().slice(0,8);
const supplierName=id=>suppliers.find(s=>s.id===id)?.name||'';
const stageLabels={Draft:['Draft','gray'],'Supplier approval':['Supplier approval','amber'],'ROKI Issue':['Awaiting issue','amber'],'ROKI Check':['Awaiting check','blue'],'ROKI Approve':['Awaiting approval','blue'],Approved:['Approved','green'],Reverted:['Returned for correction','purple'],Rejected:['Rejected','red']};
const statusBadge=s=>{const [label,color]=stageLabels[s]||[s,'gray'];return `<span class="badge ${color}">${esc(label)}</span>`};
const statusPill=(s,c)=>`<span class="badge ${c}">${esc(s)}</span>`;
function seedCosts(format){return {components:[{name:'Housing',code:'COMP-001',origin:'Local',rate:18,qty:1},{name:'Filter element',code:'COMP-002',origin:'Import',rate:12,qty:1}],material:[{name:'Resin',weight:.2,runner:0,rate:50}],process:[{name:'Assembly',machine:'Line 01',cavity:1,rate:.2,time:40}],investment:[{name:'Assembly jig',amount:12000,volume:12000}],packing:[{name:'Returnable tray',amount:10,qty:20}],management:format==='Assembly'?.5:0,loss:format==='Assembly'?3:0,profit:format==='Assembly'?15:0,basis:format==='Assembly'?'process':'subtotal'};}
function totals(c){const componentBase=c.components.reduce((s,r)=>s+Number(r.rate)*Number(r.qty),0);const A=componentBase*(1+Number(c.management)/100);const B=c.material.reduce((s,r)=>s+(Number(r.weight)+Number(r.runner))*Number(r.rate),0)*(1+Number(c.loss)/100);const C=c.process.reduce((s,r)=>s+Number(r.rate)*Number(r.time)/Number(r.cavity),0);const D=c.investment.reduce((s,r)=>s+Number(r.amount)/Number(r.volume),0);const E=c.packing.reduce((s,r)=>s+Number(r.amount)/Number(r.qty),0);const subtotal=A+B+C+D+E;const profit=(c.basis==='process'?C:subtotal)*Number(c.profit)/100;return {A,B,C,D,E,subtotal,profit,total:Math.round((subtotal+profit+Number.EPSILON)*100)/100};}
function seed(){const items=[
{id:'i1',code:'RK-1042',name:'Air cleaner housing',supplier:'s1',format:'Single Part',price:128.5,last:'2026-08-01',next:'2026-11-01',cadence:3},
{id:'i2',code:'RK-2086',name:'Filter element assembly',supplier:'s2',format:'Assembly',price:52,last:'2026-08-18',next:'2026-11-18',cadence:3},
{id:'i3',code:'RK-1038',name:'Intake cover, upper',supplier:'s1',format:'Single Part',price:82,last:'2026-09-01',next:'2026-12-01',cadence:3},
{id:'i4',code:'RK-1042',name:'Air cleaner housing',supplier:'s2',format:'Single Part',price:130,last:'2026-08-15',next:'2026-11-15',cadence:3},
{id:'i5',code:'RK-2091',name:'Air duct assembly',supplier:'s1',format:'Assembly',price:54,last:'2026-08-18',next:'2026-11-18',cadence:3},
{id:'i6',code:'RK-3014',name:'Rubber seal ring',supplier:'s2',format:'Single Part',price:15.2,last:'2026-10-01',next:'2027-01-01',cadence:3}
];
const stages=['ROKI Check','Supplier approval','Approved','ROKI Issue','Reverted','ROKI Approve'];
const quotes=items.map((item,i)=>{const costs=seedCosts(item.format);return {id:'Q-2026-00'+(i+1),item:item.id,supplier:item.supplier,format:item.format,revision:2,status:stages[i],previous:item.price,costs,total:totals(costs).total,quantity:12000,drawing:'04',effective:'2027-01-01',remark:i===4?'Tooling and packing assumptions updated. Please confirm the revised production volume.':'Revised component sourcing and production costs for the next price cycle.',attachments:[],trail:[{action:'Supplier issued quotation',user:'Supplier issuer',at:'17 Nov 2026, 09:10 ICT'},...(i!==1?[{action:'Supplier approved and submitted to ROKI',user:'Supplier approver',at:'17 Nov 2026, 10:30 ICT'}]:[]),...(i===4?[{action:'ROKI returned for correction',user:'ROKI checker',at:'18 Nov 2026, 09:00 ICT',reason:'Confirm annual production volume before resubmitting.'}]:[])],versions:[],requestedBy:null};});
const approved=quotes[2];items[2].price=approved.total;items[2].last='2026-11-17';
return {items,quotes,notifications:[{id:'N-DEMO-001',supplier:'s1',items:['i1'],created:'17 Nov 2026, 08:30 ICT',by:'Somchai K.',due:'2026-12-01',message:'Please review your current price and submit an updated quotation with a reason for any change.',read:false}],audit:[{action:'Demo workspace initialized',user:'Demo data',at:'18 Nov 2026, 08:00 ICT'}]};}
let db;try{db=JSON.parse(localStorage.getItem(STORE))||seed()}catch{db=seed()}
const persist=()=>localStorage.setItem(STORE,JSON.stringify(db));persist();
let user=users.find(u=>u.id===sessionStorage.getItem('roki-session-'+portal)&&u.portal===portal);
let selected=new Set(),search='',filterStatus='',filterSupplier='',formatFilter='',costTab='components',editing=null,editorAttachments=[];
const itemOf=q=>db.items.find(i=>i.id===q.item);
const visibleQuotes=()=>db.quotes.filter(q=>portal==='supplier'?q.supplier===user.supplier:['ROKI Issue','ROKI Check','ROKI Approve','Approved','Reverted','Rejected'].includes(q.status));
const currentItems=()=>db.items.filter(i=>portal==='roki'||i.supplier===user.supplier);
const pendingForRole=q=>portal==='supplier'?(user.role==='Approve'&&q.status==='Supplier approval'):q.status==='ROKI '+user.role;
const canEdit=q=>portal==='supplier'&&user.role==='Issue'&&q.supplier===user.supplier&&['Draft','Reverted'].includes(q.status);
const navs=()=>portal==='roki'?[['grid','overview','Overview'],['compare','quotes','Price comparison'],['check','approvals','Approval inbox'],['clock','schedule','Price update schedule'],['file','history','Revision history'],['box','parts','Parts & assemblies'],['users','suppliers','Supplier accounts'],['download','exports','Approved price export']]:[['grid','overview','Overview'],['file','quotes','My quotations'],['check','approvals','Approval inbox'],['bell','requests','Price update requests'],['clock','history','Revision history'],['box','parts','My parts']];
function actionButton(label,action,primary=false,extra=''){return `<button type="button" class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${esc(label)}</button>`}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500)}
function go(route){search='';filterStatus='';filterSupplier='';formatFilter='';selected.clear();location.hash=route;render()}
function audit(action,reason=''){db.audit.unshift({action,user:user.name,at:timestamp(),reason});persist()}
function login(){const available=users.filter(u=>u.portal===portal);document.getElementById('app').innerHTML=`<div class="login-layout"><section class="login-story">${logo()}<div><p style="text-transform:uppercase;letter-spacing:2px;font-size:10px">${portal==='roki'?'Purchasing workspace':'Supplier workspace'}</p><h1>${portal==='roki'?'Clear prices. Confident decisions.':'Your quotations, connected to ROKI.'}</h1><p>${portal==='roki'?'Compare cost revisions, manage price review requests, and move quotations through a traceable approval workflow.':'Prepare detailed quotations, approve them within your company, and respond to price update requests in one place.'}</p></div><small>ROKI (THAILAND) CO., LTD. · Supplier Price</small></section><section class="login-main"><div class="login-form"><p class="eyebrow">${portal==='roki'?'ROKI':'Supplier'} portal</p><h2>Welcome to your workspace</h2><p>Select an individual demo account to explore its role and permissions.</p><label for="demo-account">Demo user account</label><select id="demo-account">${available.map(u=>`<option value="${u.id}">${esc(u.name)} · ${u.role}${u.supplier?' · '+esc(supplierName(u.supplier)):''}</option>`).join('')}</select><div id="account-info" class="account-info"></div>${actionButton('Enter '+(portal==='roki'?'ROKI':'supplier')+' workspace','login',true)}<a class="portal-switch" href="${portal==='roki'?'supplier':'roki'}.html">Open ${portal==='roki'?'Supplier':'ROKI'} portal →</a><div class="login-note">Local interactive demo · No password authentication or server access control. Changes are saved in this browser. Supplier notifications are simulated; no emails are sent.</div></div></section></div>`;accountInfo();document.getElementById('demo-account').onchange=accountInfo;}
function accountInfo(){const u=users.find(u=>u.id===document.getElementById('demo-account').value);document.getElementById('account-info').innerHTML=`<strong>${esc(u.email)}</strong><br>${u.supplier?esc(supplierName(u.supplier)):'ROKI Thailand'} · ${u.role} role<br>${u.portal==='supplier'?(u.role==='Issue'?'Create and revise quotations; issue them for supplier approval.':'Review and approve your company’s quotations before submission to ROKI.'):(u.role==='Issue'?'Issue submitted quotations into ROKI review.':u.role==='Check'?'Check quotation costs and change reasons.':'Give final approval to checked quotations.')}`;}
function shell(content,page){const nav=navs();const pending=visibleQuotes().filter(pendingForRole).length;return `<div class="layout"><aside class="sidebar"><a href="#overview" class="brand">${logo()}</a><div class="portal-tag">${portal==='roki'?'ROKI PURCHASING':'SUPPLIER WORKSPACE'}</div><nav class="side-nav">${nav.map(([n,id,t])=>`<a class="${page===id?'active':''}" href="#${id}">${icon(n)}<span>${t}</span>${id==='approvals'&&pending?`<b class="count">${pending}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="support-card"><strong>${portal==='roki'?'Review before sending':'Your company’s quotations'}</strong>${portal==='roki'?'Price update notifications are sent only when you choose to send.':'Issue → Supplier Approve<br>Then ROKI Issue → Check → Approve'}</div><div class="user"><div class="avatar">${esc(user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><strong>${esc(user.name)}</strong><small>${esc(user.role)} · ${portal==='roki'?'ROKI':esc(suppliers.find(s=>s.id===user.supplier).code)}</small></div></div></div></aside><main class="main"><div class="demo-banner"><span>Interactive local demo · Browser data only · Notifications & e-signatures are simulated</span><a href="${portal==='roki'?'supplier':'roki'}.html" target="_blank" rel="noopener">Open ${portal==='roki'?'Supplier':'ROKI'} portal ↗</a></div><header class="topline"><div class="breadcrumb">${portal==='roki'?'ROKI workspace':esc(supplierName(user.supplier))}<span>›</span><strong>${esc(nav.find(x=>x[1]===page)?.[2]||'Quotation')}</strong></div><div class="top-actions"><span>${esc(user.name)} · ${esc(user.role)}</span><button data-action="logout" class="link-button">Switch account</button></div></header><nav class="mobile-nav">${nav.map(([,id,t])=>`<a href="#${id}" class="${page===id?'active':''}">${t}</a>`).join('')}</nav><div class="content">${content}</div></main></div>`}
function heading(eyebrow,title,sub,actions=''){return `<div class="heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}
function stats(){const quotes=visibleQuotes();const due=currentItems().filter(i=>i.next<=TODAY).length;const req=db.notifications.filter(n=>n.supplier===user.supplier);return `<div class="metrics">${portal==='roki'?metric('Supplier companies',String(suppliers.length),'Individual Issue & Approve accounts','users'):metric('Your part / supplier pairs',String(currentItems().length),'Assigned to your company','box')}${metric('Awaiting your action',String(quotes.filter(pendingForRole).length),user.role+' role','check').replace('class="metric ','class="metric attention ')}${portal==='roki'?metric('Due for price review',String(due),'Manually review and notify','clock').replace('class="metric ','class="metric alert '):metric('Price update requests',String(req.length),'Requests received from ROKI','bell').replace('class="metric ','class="metric review ')}${metric('Approved quotations',String(quotes.filter(q=>q.status==='Approved').length),'Final ROKI approval completed','chart').replace('class="metric ','class="metric success ')}</div>`}
function quoteTable(quotes){if(!quotes.length)return '<div class="empty">No quotations match this view.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Part / quotation</th>${portal==='roki'?'<th>Supplier</th>':''}<th class="num">Previous · THB</th><th class="num">Proposed · THB</th><th class="num">Change</th><th>Status</th><th></th></tr></thead><tbody>${quotes.map(q=>{const i=itemOf(q),diff=q.total-q.previous,pct=q.previous?diff/q.previous*100:0;return `<tr class="clickable" data-open="${q.id}"><td><strong>${esc(i.code)}</strong><small>${esc(i.name)} · ${esc(q.id)}</small></td>${portal==='roki'?`<td>${esc(supplierName(q.supplier))}<small>${esc(q.format)} · Rev. ${q.revision}</small></td>`:''}<td class="num">${cash(q.previous)}</td><td class="num price">${cash(q.total)}</td><td class="num delta ${diff<=0?'down':'up'}">${pct>0?'+':''}${pct.toFixed(2)}%</td><td>${statusBadge(q.status)}</td><td><a href="#quote/${q.id}" class="link-button">View</a></td></tr>`}).join('')}</tbody></table></div><div class="table-footer"><span>${quotes.length} quotation${quotes.length===1?'':'s'} · THB per piece</span><span>Original and revised values retained</span></div>`}
function overview(){return heading(portal==='roki'?'Procurement overview':'Supplier overview',portal==='roki'?'Supplier price workspace':'Your quotation workspace',portal==='roki'?'Review price revisions, follow approvals, and plan the next supplier update.':'Prepare quotations and follow each revision from your team through ROKI approval.',portal==='supplier'&&user.role==='Issue'?actionButton('New quotation','new',true):`<a href="#${portal==='roki'?'schedule':'approvals'}" class="button primary">${portal==='roki'?'Review price schedule':'Open approval inbox'} ${icon('arrow')}</a>`)+stats()+`<section class="panel"><div class="panel-title"><div><h2>Quotations needing your action</h2><small>Assigned to your current role</small></div><a class="text-link" href="#quotes">All quotations ${icon('arrow')}</a></div>${quoteTable(visibleQuotes().filter(pendingForRole))}</section><div class="lower"><section class="panel"><div class="panel-title"><h2>Recent activity</h2></div>${activityEntries(visibleQuotes().flatMap(q=>q.trail.map(t=>({...t,quote:q.id}))).slice(-4).reverse())}</section><section class="panel"><div class="panel-title"><h2>${portal==='roki'?'Price review cycle':'Your submission workflow'}</h2>${statusPill('Action required','amber')}</div><div class="body-pad"><p>${portal==='roki'?'Review due item–supplier pairs before sending an update request. Multiple suppliers for the same item are tracked separately.':'An issuer prepares the quotation. Your company’s approver reviews and submits it to ROKI. ROKI then completes Issue, Check, and Approve.'}</p><a href="#${portal==='roki'?'schedule':'requests'}" class="button" style="margin-top:18px">${portal==='roki'?'Open price update schedule':'View update requests'} ${icon('arrow')}</a></div></section></div>`}
function activityEntries(entries){return entries.length?entries.map(t=>`<div class="audit-entry"><strong>${esc(t.action)}</strong>${t.quote?` · <a href="#quote/${esc(t.quote)}" class="link-button">${esc(t.quote)}</a>`:''}<small>${esc(t.user)} · ${esc(t.at)}</small>${t.reason?`<p>${esc(t.reason)}</p>`:''}</div>`).join(''):'<div class="empty">No activity yet.</div>'}
function quoteList(approval=false){let quotes=visibleQuotes();if(approval)quotes=quotes.filter(pendingForRole);quotes=quotes.filter(q=>{const i=itemOf(q);return `${i.code} ${i.name} ${q.id} ${supplierName(q.supplier)}`.toLowerCase().includes(search.toLowerCase())&&(!filterStatus||q.status===filterStatus)&&(!formatFilter||q.format===formatFilter)});return heading(approval?'Your review queue':'Quotations',approval?'Approval inbox':portal==='roki'?'Supplier price comparison':'My quotations',approval?'Review quotations assigned to your current account and role.':'Compare previous and proposed unit prices and open the detailed breakdown.',portal==='supplier'&&user.role==='Issue'?actionButton('New quotation','new',true):'')+`<section class="panel"><div class="filters"><div class="search">${icon('search')}<input id="search" value="${esc(search)}" placeholder="Search part, supplier or quotation…"></div><select id="status-filter"><option value="">All statuses</option>${Object.keys(stageLabels).map(s=>`<option ${filterStatus===s?'selected':''}>${s}</option>`).join('')}</select><select id="format-filter"><option value="">All formats</option>${['Single Part','Assembly'].map(f=>`<option ${formatFilter===f?'selected':''}>${f}</option>`).join('')}</select><span class="filter-right">Prices in THB / piece</span></div>${quoteTable(quotes)}</section>`}
function schedule(){const due=i=>i.next<TODAY?'Overdue':i.next===TODAY?'Due today':'Upcoming';const items=db.items.filter(i=>`${i.code} ${i.name} ${supplierName(i.supplier)}`.toLowerCase().includes(search.toLowerCase())&&(!filterSupplier||i.supplier===filterSupplier)&&(!filterStatus||due(i)===filterStatus));return heading('Supplier price review','Price update schedule','Recheck which items and suppliers need an update, then manually send requests.')+`<div class="highlight-note">${icon('clock')}　Scheduled dates flag what needs review. Notifications are sent only when you select items and click Send.</div><section class="panel"><div class="panel-title"><div><h2>Item–supplier review list</h2><small>Review date: 18 November 2026 · Each supplier is tracked separately.</small></div>${statusPill(db.items.filter(i=>i.next<=TODAY).length+' pairs due','amber')}</div><div class="filters"><div class="search">${icon('search')}<input id="search" value="${esc(search)}" placeholder="Search item or supplier…"></div><select id="supplier-filter"><option value="">All suppliers</option>${suppliers.map(s=>`<option value="${s.id}" ${filterSupplier===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="status-filter"><option value="">All review dates</option>${['Overdue','Due today','Upcoming'].map(s=>`<option ${filterStatus===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table schedule-table"><thead><tr><th><input type="checkbox" id="select-all" aria-label="Select all visible item supplier pairs" ${items.length&&items.every(i=>selected.has(i.id))?'checked':''}></th><th>Item / supplier</th><th class="num">Current price</th><th>Next review</th><th>Status</th><th>Last notification</th><th></th></tr></thead><tbody>${items.map(i=>{const status=due(i);const notice=[...db.notifications].reverse().find(n=>n.items.includes(i.id));return `<tr class="${status==='Overdue'?'overdue':status==='Due today'?'due':''}"><td><input type="checkbox" data-select="${i.id}" aria-label="Select ${esc(i.code+' '+supplierName(i.supplier))}" ${selected.has(i.id)?'checked':''}></td><td><strong>${esc(i.code)} · ${esc(i.name)}</strong><small>${esc(supplierName(i.supplier))}</small></td><td class="num price">${cash(i.price)}</td><td>${date(i.next)}<small>Every ${i.cadence} month${i.cadence===1?'':'s'}</small></td><td>${statusPill(status,status==='Overdue'?'red':status==='Due today'?'amber':'gray')}</td><td>${notice?statusPill('Requested','blue'):'<span style="color:#9ba8b8">Not notified</span>'}${notice?`<small>${esc(notice.created)}</small>`:''}</td><td><button class="date-button" data-schedule="${i.id}">Edit schedule</button></td></tr>`}).join('')}</tbody></table>${!items.length?'<div class="empty">No item–supplier pairs match these filters.</div>':''}</div><div class="selection-bar"><span><strong>${selected.size}</strong> item–supplier pairs selected · ${new Set([...selected].map(id=>db.items.find(i=>i.id===id)?.supplier)).size} suppliers</span><button class="button primary" data-action="notify" ${!selected.size?'disabled':''}>${icon('bell')}Review & send notifications</button></div></section><section class="panel" style="margin-top:22px"><div class="panel-title"><h2>Notification log</h2><span class="badge gray">Demo deliveries</span></div>${db.notifications.length?[...db.notifications].reverse().map(n=>`<div class="notification-card"><div><h3>${esc(supplierName(n.supplier))} · ${n.items.length} item${n.items.length===1?'':'s'}</h3><p>${n.items.map(id=>esc(db.items.find(i=>i.id===id).code)).join(', ')} · Response due ${date(n.due)}</p><small>${esc(n.by)} · ${esc(n.created)}</small></div>${statusPill('Sent in demo','green')}</div>`).join(''):'<div class="empty">No notifications sent.</div>'}</section>`}
function requests(){const notes=db.notifications.filter(n=>n.supplier===user.supplier).slice().reverse();return heading('Requests from ROKI','Price update requests','Review the requested items and prepare a quotation for your company’s approval.')+`<section class="panel">${notes.length?notes.map(n=>`<div class="notification-card"><div><h3>Price update requested · ${esc(n.id)}</h3><p>${esc(n.message)}</p><p style="margin-top:10px">Response due <strong>${date(n.due)}</strong> · Sent by ${esc(n.by)}</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:13px">${n.items.map(id=>{const i=db.items.find(x=>x.id===id),responded=db.quotes.some(q=>q.requestedBy===n.id&&q.item===id&&!['Draft','Reverted','Rejected','Supplier approval'].includes(q.status));return `<div style="display:flex;gap:9px;align-items:center"><span style="font-size:11px">${esc(i.code)} · ${esc(i.name)}</span>${responded?statusPill('Submitted','green'):user.role==='Issue'?`<button class="button" data-request="${n.id}" data-item="${i.id}">Prepare update</button>`:statusPill('Awaiting issuer','amber')}</div>`}).join('')}</div><small style="display:block;margin-top:15px">${esc(n.created)}</small></div>${statusPill('Update requested','blue')}</div>`).join(''):'<div class="empty">No price update requests received.</div>'}</section>`}
function parts(){return heading('Part master',portal==='roki'?'Parts & assemblies':'My parts','Current approved prices and review dates for each item–supplier pair.')+`<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Part / item code</th><th>Supplier</th><th>Format</th><th class="num">Approved · THB</th><th>Last update</th><th>Next review</th></tr></thead><tbody>${currentItems().map(i=>`<tr><td><strong>${esc(i.code)}</strong><small>${esc(i.name)}</small></td><td>${esc(supplierName(i.supplier))}</td><td>${esc(i.format)}</td><td class="num price">${cash(i.price)}</td><td>${date(i.last)}</td><td>${date(i.next)}</td></tr>`).join('')}</tbody></table></div></section>`}
function accounts(){return heading('Supplier directory','Supplier accounts','Individual Issue and Approve accounts grouped by supplier company.')+suppliers.map(s=>`<section class="panel" style="margin-bottom:20px"><div class="panel-title"><div><h2>${esc(s.name)}</h2><small>${esc(s.code)} · ${db.items.filter(i=>i.supplier===s.id).length} item–supplier pairs</small></div>${statusPill('Active','green')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Permissions</th></tr></thead><tbody>${users.filter(u=>u.supplier===s.id).map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${statusPill(u.role,u.role==='Issue'?'blue':'green')}</td><td>${u.role==='Issue'?'Prepare, revise & issue quotations':'Approve and submit quotations to ROKI'}</td></tr>`).join('')}</tbody></table></div></section>`).join('')+'<p class="footer-note">Demo accounts are predefined. Production user provisioning and authentication require a server.</p>'}
function historyView(){const entries=visibleQuotes().flatMap(q=>q.trail.map(t=>({...t,quote:q.id}))).reverse();return heading('Traceability','Revision history','Quotation revisions, approval actions, and reasons are retained together.')+`<section class="panel"><div class="panel-title"><h2>Quotation audit trail</h2></div>${activityEntries(entries)}</section>`}
function exportsView(){const approved=visibleQuotes().filter(q=>q.status==='Approved');return heading('Approved quotations','Approved price export','Export final approved prices for review before preparing your SAP upload.',actionButton('Download approved prices CSV','export',true))+`<div class="highlight-note blue">This demo exports CSV. The actual SAP upload format has not been supplied; this file is not an SAP import template.</div><section class="panel"><div class="panel-title"><h2>Approved quotations only</h2>${statusPill(approved.length+' approved','green')}</div>${quoteTable(approved)}</section>`}
function quoteDetail(id){const q=visibleQuotes().find(q=>q.id===id);if(!q)return '<div class="empty">Quotation unavailable for this account. <a href="#quotes" class="link-button">Return to quotations</a></div>';const item=itemOf(q),t=totals(q.costs),labels=q.format==='Assembly'?[['A','Component parts'],['B','Material'],['C','Process'],['D','Investment'],['E','Packing & transport']]:[['B','Material'],['A','Component parts'],['C','Process'],['E','Packing & transport'],['D','Equipment']];const steps=['Supplier Issue','Supplier Approve','ROKI Issue','ROKI Check','ROKI Approve'];const current={Draft:0,Reverted:0,'Supplier approval':1,'ROKI Issue':2,'ROKI Check':3,'ROKI Approve':4,Approved:5,Rejected:-1}[q.status];return heading(q.format+' · '+q.id,item.name,item.code+' / '+supplierName(q.supplier)+' / Revision '+q.revision,`<a href="#quotes" class="button">Back to quotations</a>${canEdit(q)?`<button class="button primary" data-edit="${q.id}">Edit quotation</button>`:''}`)+`<div class="page-grid"><div class="stack"><section class="panel"><div class="status-strip">${statusBadge(q.status)}<p>Supplier Issue → Supplier Approve → ROKI Issue → Check → Approve</p></div><div class="body-pad detail-meta"><div><label>Effective date</label><p>${date(q.effective)}</p></div><div><label>Monthly quantity</label><p>${Number(q.quantity).toLocaleString()} pcs</p></div><div><label>Drawing revision</label><p>${esc(q.drawing)}</p></div><div><label>Format</label><p>${esc(q.format)}</p></div></div><div class="detail-prices"><div><label>Previous approved price</label><strong>฿${cash(q.previous)}</strong></div>${icon('arrow')}<div><label>Proposed unit price</label><strong>฿${cash(q.total)}</strong></div></div><div class="q-change" style="padding:0 20px 20px;color:${q.total<=q.previous?'var(--green)':'var(--red)'};font-size:11px">${q.total<=q.previous?'↘':'↗'} ${cash(q.total-q.previous)} THB / pc · ${(100*(q.total-q.previous)/q.previous).toFixed(2)}% from previous price</div></section><section class="panel"><div class="panel-title"><h2>Cost breakdown</h2><span class="badge gray">THB / piece</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Cost category</th><th>Details</th><th class="num">Amount · THB</th></tr></thead><tbody>${labels.map(([key,label])=>`<tr><td><strong>${label}</strong></td><td>${key==='A'?q.costs.components.length+' component lines':key==='B'?q.costs.loss+'% material loss':key==='C'?q.costs.process.length+' processes':key==='D'?q.costs.investment.length+' investment lines':q.costs.packing.length+' packing lines'}</td><td class="num price">${cash(t[key])}</td></tr>`).join('')}<tr><td>Profit & admin</td><td>${q.costs.profit}% × ${q.costs.basis==='process'?'process cost':'subtotal'}</td><td class="num">${cash(t.profit)}</td></tr><tr style="background:#edf5ff"><td><strong>Total quoted price</strong></td><td></td><td class="num price" style="color:var(--blue)">${cash(q.total)}</td></tr></tbody></table></div></section><section class="panel"><div class="panel-title"><h2>Revision reason & supporting files</h2></div><div class="body-pad"><p>${esc(q.remark)}</p>${q.attachments.length?`<div class="attachment-list">${q.attachments.map((f,i)=>`<button class="attachment-pill" data-file="${i}" data-quote="${q.id}">${f.kind==='drawing'?'PDF drawing':'Part image'} · ${esc(f.name)} ↓</button>`).join('')}</div>`:'<p style="margin-top:15px;color:#a0adbd;font-size:10px">No attachments for this demo quotation.</p>'}</div></section><section class="panel"><div class="panel-title"><h2>Revision & approval trail</h2><span style="font-size:10px;color:#99a7b7">${q.versions.length} saved previous revisions</span></div>${activityEntries(q.trail)}${q.versions.length?`<div class="body-pad"><h3>Previous versions</h3>${q.versions.map(v=>`<p style="margin-top:12px">Revision ${v.revision} · ฿${cash(v.total)} · ${esc(v.status)}<br>${esc(v.remark)}</p>`).join('')}</div>`:''}</section></div><aside class="stack"><section class="panel"><div class="panel-title"><h2>Approval progress</h2></div><div class="workflow-list">${steps.map((s,i)=>`<div class="workflow-row ${current>i?'done':current===i?'current':''}"><i>${current>i?'✓':i+1}</i><span>${s}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h2>Your next action</h2><span class="badge gray">${esc(user.role)}</span></div><div class="body-pad">${quoteActions(q)}</div></section><div class="highlight-note blue" style="margin-bottom:0">Supplier approval uses account confirmation. ROKI review actions include a simulated e-sign confirmation in this demo.</div></aside></div>`}
function quoteActions(q){if(canEdit(q))return `<p>Prepare the revised costs and add a reason before issuing for supplier approval.</p><button class="button primary" style="width:100%;margin-top:15px" data-edit="${q.id}">Edit & issue quotation</button>`;if(pendingForRole(q))return `<p>${portal==='supplier'?'Review the costs and remarks, then approve to submit this quotation to ROKI.':'Review the quotation before completing your assigned '+user.role.toLowerCase()+' step.'}</p><button class="button primary" style="width:100%;margin-top:15px" data-transition="advance" data-id="${q.id}">${portal==='supplier'?'Approve & submit to ROKI':'Sign & complete '+user.role.toLowerCase()}</button><button class="button" style="width:100%;margin-top:10px;color:#7650a4;border-color:#d7bff1" data-transition="revert" data-id="${q.id}">Return for correction</button>${portal==='roki'?`<button class="button danger" style="width:100%;margin-top:10px" data-transition="reject" data-id="${q.id}">Reject quotation</button>`:''}`;return `<p>${q.status==='Approved'?'This quotation has completed final ROKI approval.':q.status==='Rejected'?'This quotation was rejected. A supplier issuer can prepare a new quotation.':'No action is assigned to your current role at this step. Switch to the appropriate account to continue the demo.'}</p>`}
let editorItem=null,editorRequest=null;
function newQuote(itemId,request){if(portal!=='supplier'||user.role!=='Issue')return toast('Only supplier issuers can prepare quotations.');editing=null;editorItem=itemId||currentItems()[0]?.id;editorRequest=request||null;editorAttachments=[];costTab='components';const item=db.items.find(i=>i.id===editorItem);window.formCosts=seedCosts(item.format);go('new');}
function editQuote(id){const q=visibleQuotes().find(q=>q.id===id);if(!q||!canEdit(q))return toast('This quotation is not editable by this account.');editing=q.id;editorItem=q.item;editorRequest=q.requestedBy;editorAttachments=structuredClone(q.attachments);window.formCosts=structuredClone(q.costs);costTab='components';go('edit/'+id)}
const fieldsFor={components:[['code','Part no.','text'],['name','Part name','text'],['origin','Origin','origin'],['rate','Unit cost','number'],['qty','Quantity','number']],material:[['name','Material','text'],['weight','Part wt · kg','number'],['runner','Runner wt · kg','number'],['rate','THB / kg','number']],process:[['name','Process','text'],['machine','Machine','text'],['rate','THB / sec','number'],['time','CT · sec / shot','number'],['cavity','Cavity count','number']],investment:[['name','Mold / die / jig','text'],['amount','Investment · THB','number'],['volume','Annual volume','number']],packing:[['name','Type','text'],['amount','Cost · THB','number'],['qty','Pieces per pack','number']]};
const categoryLabels={components:'Components',material:'Material',process:'Process',investment:'Investment / equipment',packing:'Packing & transport'};
function editor(){if(portal!=='supplier'||user.role!=='Issue')return '<div class="empty">Only supplier issuers may edit quotations.</div>';if(!window.formCosts){const id=location.hash.split('/')[1],q=db.quotes.find(q=>q.id===id&&q.supplier===user.supplier);if(q&&canEdit(q)){editing=q.id;editorItem=q.item;editorRequest=q.requestedBy;editorAttachments=structuredClone(q.attachments);window.formCosts=structuredClone(q.costs)}else{editorItem=currentItems()[0].id;window.formCosts=seedCosts(currentItems()[0].format)}}const q=db.quotes.find(q=>q.id===editing),i=db.items.find(i=>i.id===editorItem);return heading(i.format+' quotation',q?'Revise your quotation':'Prepare a price quotation','Enter costs and a revision reason, then issue the quotation to your supplier approver.',`<a href="#quotes" class="button">Cancel</a>`)+`<form id="quote-form"><div class="page-grid"><div class="stack"><section class="panel"><div class="panel-title"><div><h2>Quotation details</h2><small>${esc(supplierName(user.supplier))} · ${esc(suppliers.find(s=>s.id===user.supplier).code)}</small></div>${statusPill('Draft','gray')}</div><div class="body-pad form-grid"><div class="field"><label for="item">Part / item <span class="req">*</span></label><select id="item" ${q?'disabled':''}>${currentItems().map(item=>`<option value="${item.id}" ${i.id===item.id?'selected':''}>${esc(item.code+' · '+item.name)}</option>`).join('')}</select></div><div class="field"><label>Quotation format</label><input readonly value="${esc(i.format)}"></div><div class="field"><label for="effective">Beginning / effective date <span class="req">*</span></label><input id="effective" type="date" value="${q?.effective||'2027-01-01'}" required></div><div class="field"><label for="quantity">Monthly quantity · pcs <span class="req">*</span></label><input id="quantity" type="number" min="1" step="1" required value="${q?.quantity||12000}"></div><div class="field"><label for="drawing">Drawing revision <span class="req">*</span></label><input id="drawing" value="${esc(q?.drawing||'04')}" required maxlength="80"></div><div class="field"><label>Previous approved price · THB</label><input readonly value="${cash(q?.previous??i.price)}"></div></div></section><section class="panel"><div class="panel-title"><div><h2>Detailed cost breakdown</h2><small>Editable inputs · Calculated expense per piece</small></div></div><div class="cost-tabs">${Object.entries(categoryLabels).map(([key,label])=>`<button type="button" class="${costTab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div><div id="cost-rows">${costRowsUI()}</div></section><section class="panel"><div class="panel-title"><h2>Revision reason & attachments</h2></div><div class="body-pad"><div class="field"><label for="remark">Reason for price change <span class="req">*</span></label><textarea id="remark" required maxlength="2000" placeholder="Explain the costs or assumptions that changed…">${esc(q?.remark||'')}</textarea></div><div class="form-grid" style="grid-template-columns:1fr 1fr;margin-top:18px"><div class="field"><label for="images">Part images · up to 10</label><input id="images" type="file" accept="image/png,image/jpeg,image/webp" multiple><small>PNG, JPG or WebP · Up to 2 MB per file in this local demo.</small></div><div class="field"><label for="drawings">Drawing documents</label><input id="drawings" type="file" accept="application/pdf" multiple><small>PDF files only · Up to 2 MB per file.</small></div></div><div id="attachment-list" class="attachment-list">${attachmentUI()}</div></div><div class="form-actions"><small>Issue → Supplier Approve → ROKI Issue → Check → Approve</small><div class="actions"><button type="button" class="button" data-action="save-draft">Save draft</button><button type="submit" class="button primary">Issue for supplier approval ${icon('arrow')}</button></div></div></section></div><aside class="stack"><section class="panel"><div class="panel-title"><h2>Calculated unit price</h2><span class="badge gray">THB / pc</span></div><div id="cost-summary">${costSummary()}</div></section><div class="highlight-note blue">${i.format==='Assembly'?'Assembly profit/admin defaults to 15% of process cost.':'Single Part profit/admin is explicit; select the applicable basis and rate.'} All input values shown here are illustrative demo data.</div></aside></div></form>`}
function rowExpense(key,r){return key==='components'?r.rate*r.qty:key==='material'?(+r.weight+ +r.runner)*r.rate:key==='process'?r.rate*r.time/r.cavity:key==='investment'?r.amount/r.volume:r.amount/r.qty}
function costRowsUI(){const c=window.formCosts,key=costTab,fields=fieldsFor[key];return `<div class="table-wrap"><table class="cost-table"><thead><tr>${fields.map(([,label])=>`<th>${label}</th>`).join('')}<th class="num">Expense</th><th></th></tr></thead><tbody>${c[key].map((r,index)=>`<tr>${fields.map(([field,label,type])=>`<td>${type==='origin'?`<select class="cost-input wide" data-cost="${index}" data-field="${field}" aria-label="${label} row ${index+1}"><option ${r.origin==='Local'?'selected':''}>Local</option><option ${r.origin==='Import'?'selected':''}>Import</option></select>`:`<input class="cost-input ${type==='text'?'wide':''}" type="${type}" data-cost="${index}" data-field="${field}" aria-label="${label} row ${index+1}" value="${esc(r[field])}" ${type==='number'?`min="${['cavity','volume','qty'].includes(field)?'0.000001':'0'}" step="any" required`:'maxlength="100" required'}>`}</td>`).join('')}<td class="num price" data-expense="${index}">${cash(rowExpense(key,r))}</td><td><button type="button" class="remove-row" data-remove="${index}" aria-label="Remove cost row ${index+1}">×</button></td></tr>`).join('')}</tbody></table>${!c[key].length?'<div class="empty">No lines in this cost category. Add a row if applicable.</div>':''}</div><div style="padding:14px 20px;display:flex;justify-content:space-between;gap:10px;align-items:center"><button type="button" class="button" data-action="add-cost">${icon('plus')}Add ${categoryLabels[key].toLowerCase()} line</button>${key==='components'?`<label style="font-size:10px;color:#8a99aa">Management % <input class="cost-input" id="management" type="number" min="0" max="100" step="any" value="${c.management}"></label>`:key==='material'?`<label style="font-size:10px;color:#8a99aa">Material loss % <input class="cost-input" id="loss" type="number" min="0" max="100" step="any" value="${c.loss}"></label>`:''}</div><div style="padding:0 20px 18px;font-size:10px;color:#8d9eb1">${key==='components'?'Expense = unit cost × quantity; management is added to the component subtotal.':key==='material'?'Expense = (part weight + runner weight) × material rate; loss is added to the subtotal. All weights in kg.':key==='process'?'Expense = rate per second × cycle time per shot ÷ cavity count.':key==='investment'?'Expense = total investment ÷ annual production volume.':'Expense = packing or transport cost ÷ quantity of pieces.'}</div>`}
function costSummary(){const c=window.formCosts,t=totals(c);return `<div class="cost-totals">${[['Components','A'],['Material, incl. loss','B'],['Process','C'],['Investment / equipment','D'],['Packing & transport','E'],['Subtotal','subtotal']].map(([label,key])=>`<div><span>${label}</span><strong>${cash(t[key])}</strong></div>`).join('')}<div><span>Profit & admin <input id="profit" aria-label="Profit and admin percentage" type="number" min="0" max="100" step="any" class="cost-input" style="width:55px;margin-left:5px" value="${c.profit}"> %</span></div><div><span>Calculation basis</span><select id="basis" style="max-width:145px"><option value="process" ${c.basis==='process'?'selected':''}>Process cost</option><option value="subtotal" ${c.basis==='subtotal'?'selected':''}>Subtotal</option></select></div><div><span>Profit & admin</span><strong>${cash(t.profit)}</strong></div><div class="grand"><span>Total unit price</span><strong data-total>${cash(t.total)}</strong></div><div class="calc-note">Demo calculation: retain full precision through the breakdown and round the final unit price to 2 decimals. Historical quotation rounding still needs confirmation.</div></div>`}
function attachmentUI(){return editorAttachments.map((f,i)=>`<span class="attachment-pill">${f.kind==='drawing'?'PDF':'Image'} · ${esc(f.name)} <button type="button" data-remove-file="${i}" aria-label="Remove ${esc(f.name)}">×</button></span>`).join('')}
async function addFiles(input){const files=[...input.files],kind=input.id==='images'?'image':'drawing';if(editorAttachments.length+files.length>14){toast('Maximum 14 files in this local demo.');input.value='';return}if(kind==='image'&&editorAttachments.filter(f=>f.kind==='image').length+files.length>10){toast('Up to 10 part images are allowed.');input.value='';return}for(const file of files){if(file.size>2*1024*1024||!(kind==='image'?['image/png','image/jpeg','image/webp'].includes(file.type):file.type==='application/pdf')){toast('Use a supported file type, maximum 2 MB per file.');continue}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});editorAttachments.push({name:file.name,type:file.type,kind,data})}document.getElementById('attachment-list').innerHTML=attachmentUI();input.value=''}
function validateCosts(c){for(const key of Object.keys(fieldsFor))for(const row of c[key])for(const [field,,type]of fieldsFor[key]){if(type==='number'){const v=row[field];if(typeof v!=='number'||!Number.isFinite(v)||v<0||(['qty','volume','cavity'].includes(field)&&v===0))return 'Enter valid costs and positive quantities, cavity counts, and production volumes.';}else if(!String(row[field]??'').trim())return 'Complete the descriptions and codes in each cost row.';}for(const key of ['profit','management','loss'])if(!Number.isFinite(c[key])||c[key]<0||c[key]>100)return 'Percentage rates must be between 0 and 100.';if(!Number.isFinite(totals(c).total)||totals(c).total<=0)return 'The calculated unit price must be greater than zero.';return ''}
function saveQuote(issue){if(portal!=='supplier'||user.role!=='Issue')return;const form=document.getElementById('quote-form');if(!form.reportValidity())return;const error=validateCosts(window.formCosts);if(error)return toast(error);const item=db.items.find(i=>i.id===editorItem&&i.supplier===user.supplier);if(!item)return toast('Select an item assigned to your company.');const old=db.quotes.find(q=>q.id===editing);if(old&&!canEdit(old))return toast('This quotation can no longer be edited.');const remark=document.getElementById('remark').value.trim();if(!remark)return toast('Add a reason for the revision.');const versions=old?structuredClone(old.versions):[];if(old&&old.status==='Reverted')versions.push({revision:old.revision,status:old.status,total:old.total,remark:old.remark,costs:structuredClone(old.costs),attachments:structuredClone(old.attachments),effective:old.effective,quantity:old.quantity,drawing:old.drawing,previous:old.previous,at:timestamp()});const q={id:old?.id||uid('Q'),item:item.id,supplier:user.supplier,format:item.format,revision:old?old.revision+(old.status==='Reverted'?1:0):Math.max(0,...db.quotes.filter(q=>q.item===item.id).map(q=>q.revision))+1,status:issue?'Supplier approval':'Draft',previous:old?.previous??item.price,costs:structuredClone(window.formCosts),total:totals(window.formCosts).total,quantity:Number(document.getElementById('quantity').value),drawing:document.getElementById('drawing').value.trim(),effective:document.getElementById('effective').value,remark,attachments:structuredClone(editorAttachments),trail:[...(old?.trail||[]),{action:issue?'Supplier issued for approval':'Supplier saved draft',user:user.name,at:timestamp()}],versions,requestedBy:editorRequest};const prior=db.quotes.slice();if(old)db.quotes=db.quotes.map(x=>x.id===old.id?q:x);else db.quotes.push(q);try{persist()}catch{db.quotes=prior;return toast('Browser storage is full. Remove some attachments and try again.')}editing=null;window.formCosts=null;go('quote/'+q.id);toast(issue?'Issued for your supplier approver to review.':'Draft saved.');}
function dialog(title,body,footer){document.getElementById('modal-root').innerHTML=`<div class="modal-shade"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-footer">${actionButton('Cancel','close')}${footer}</footer></section></div>`;document.querySelector('.dialog button')?.focus();}
function closeDialog(){document.getElementById('modal-root').innerHTML=''}
let transitionPending=null;
function transitionDialog(id,kind){const q=visibleQuotes().find(q=>q.id===id);if(!q||!pendingForRole(q))return toast('This action is not assigned to your account.');transitionPending={id,kind};const advance=kind==='advance';dialog(advance?(portal==='supplier'?'Approve supplier quotation':'Confirm ROKI '+user.role.toLowerCase()):kind==='revert'?'Return quotation for correction':'Reject quotation',`<p><strong>${esc(q.id)}</strong> · ${esc(itemOf(q).name)}<br>Proposed unit price <strong>฿${cash(q.total)}</strong></p><p style="margin-top:15px">${advance?(portal==='supplier'?'Approving submits this quotation to the ROKI Issue queue.':'This records a simulated e-sign confirmation for '+esc(user.name)+'.'):(kind==='revert'?'Return to the supplier issuer for correction. A reason is required.':'Reject this quotation. The supplier must prepare a new quotation. A reason is required.')}</p><div class="field"><label for="action-reason">${advance?'Review note (optional)':'Reason *'}</label><textarea id="action-reason" maxlength="1000" placeholder="${advance?'Add a review note…':'Explain what needs to change…'}"></textarea></div>${advance?`<label style="display:flex;gap:9px;font-size:11px;color:#75879e;align-items:flex-start;margin-top:18px"><input id="confirm-action" type="checkbox">I confirm this review as ${esc(user.name)}, ${esc(user.role)}.</label>`:''}`,actionButton(advance?'Confirm '+(portal==='supplier'?'approval':'review'):kind==='revert'?'Return for correction':'Reject quotation','confirm-transition',true));}
function confirmTransition(){if(!transitionPending)return;const {id,kind}=transitionPending,q=visibleQuotes().find(q=>q.id===id);if(!q||!pendingForRole(q))return toast('Quotation is no longer assigned to this role.');const reason=document.getElementById('action-reason').value.trim();if(kind!=='advance'&&!reason)return toast('A reason is required.');if(kind==='advance'&&!document.getElementById('confirm-action').checked)return toast('Confirm your review before continuing.');let action;if(kind==='revert'){q.status='Reverted';action='Returned to supplier issuer for correction';}else if(kind==='reject'){q.status='Rejected';action='ROKI rejected quotation';}else{const next={'Supplier approval':'ROKI Issue','ROKI Issue':'ROKI Check','ROKI Check':'ROKI Approve','ROKI Approve':'Approved'};const old=q.status;q.status=next[old];action=portal==='supplier'?'Supplier approved and submitted to ROKI':'ROKI '+user.role+' completed · demo e-sign';if(q.status==='Approved'){const item=itemOf(q);item.price=q.total;item.last=TODAY;}}
q.trail.push({action,user:user.name,at:timestamp(),reason});audit(action+' · '+q.id,reason);closeDialog();transitionPending=null;render();toast('Quotation updated: '+stageLabels[q.status][0]);}
function notifyDialog(){if(portal!=='roki'||!selected.size)return;const items=db.items.filter(i=>selected.has(i.id));dialog('Review supplier notifications',`<p>${items.length} selected item–supplier pairs will be grouped into ${new Set(items.map(i=>i.supplier)).size} supplier requests. Only these selected pairs will be included.</p>${items.map(i=>`<div class="preview-item"><strong>${esc(i.code)} · ${esc(i.name)}</strong><br><small>${esc(supplierName(i.supplier))} · Current price ฿${cash(i.price)}</small></div>`).join('')}<div class="field"><label for="response-due">Supplier response due date *</label><input id="response-due" type="date" min="${TODAY}" value="2026-12-01"></div><div class="field"><label for="request-message">Message to suppliers *</label><textarea id="request-message" maxlength="2000">Please review your current prices and submit updated quotations. Include a reason for any price change.</textarea></div><div class="highlight-note" style="margin:18px 0 0">Local demo: this creates requests in the Supplier portal and a notification log. No email is sent.</div>`,actionButton('Send selected notifications','send-notifications',true));}
function sendNotifications(){if(portal!=='roki')return;const due=document.getElementById('response-due').value,message=document.getElementById('request-message').value.trim();if(!due||due<TODAY||!message)return toast('Add a response date on or after today and a message.');const items=db.items.filter(i=>selected.has(i.id));if(!items.length)return toast('Select item–supplier pairs first.');const groups=new Map();for(const i of items){if(!groups.has(i.supplier))groups.set(i.supplier,[]);groups.get(i.supplier).push(i.id)}for(const [supplier,ids]of groups)db.notifications.push({id:uid('N'),supplier,items:ids,created:timestamp(),by:user.name,due,message,read:false});audit('Manually sent '+items.length+' item–supplier update requests in demo');closeDialog();selected.clear();render();toast('Requests sent to supplier portals in the demo. No email sent.');}
let scheduleEdit=null;
function editSchedule(id){if(portal!=='roki')return;const item=db.items.find(i=>i.id===id);scheduleEdit=id;dialog('Edit price review schedule',`<p>${esc(item.code)} · ${esc(supplierName(item.supplier))}</p><div class="field"><label for="next-review">Next review date *</label><input id="next-review" type="date" value="${item.next}"></div><div class="field"><label for="cadence">Review interval</label><select id="cadence"><option value="1" ${item.cadence===1?'selected':''}>Every month</option><option value="3" ${item.cadence===3?'selected':''}>Every 3 months</option></select></div><p style="margin-top:18px">Saving a schedule never sends a notification. Next review dates are managed manually in this demo.</p>`,actionButton('Save schedule','save-schedule',true));}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){if(portal!=='roki')return;const rows=[['Quotation','Part code','Supplier','Format','Revision','Approved price THB','Effective date','Status'],...db.quotes.filter(q=>q.status==='Approved').map(q=>[q.id,itemOf(q).code,supplierName(q.supplier),q.format,q.revision,q.total.toFixed(2),q.effective,q.status])];const cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download('roki-approved-prices-demo.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'));toast('Approved prices CSV downloaded. This is not an SAP upload format.');}
function route(){return location.hash.slice(1)||'overview'}
function render(){if(!user)return login();const r=route(),page=r.split('/')[0];let content;try{if(page==='quote')content=quoteDetail(r.split('/')[1]);else if(['new','edit'].includes(page))content=editor();else{const views={overview,quotes:()=>quoteList(),approvals:()=>quoteList(true),schedule,requests,parts,suppliers:accounts,history:historyView,exports:exportsView};const valid=navs().some(n=>n[1]===page);content=valid&&views[page]?views[page]():'<div class="empty">This page is unavailable in this portal. <a href="#overview">Return to overview</a></div>'}document.getElementById('app').innerHTML=shell(content,page);bindInputs()}catch(e){console.error(e);document.getElementById('app').innerHTML=shell('<div class="empty">This view could not be loaded. <a href="#overview">Return to overview</a></div>',page)}}
function refreshRows(){document.getElementById('cost-rows').innerHTML=costRowsUI();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===costTab));bindCostInputs()}
function refreshTotals(){const active=document.activeElement,focusedId=active?.id;const t=totals(window.formCosts);document.querySelectorAll('[data-expense]').forEach(el=>el.textContent=cash(rowExpense(costTab,window.formCosts[costTab][+el.dataset.expense])));if(focusedId==='profit'||focusedId==='basis'){document.querySelector('[data-total]').textContent=cash(t.total);const strongs=document.querySelectorAll('.cost-totals>div>strong');if(strongs[6])strongs[6].textContent=cash(t.profit);}else{document.getElementById('cost-summary').innerHTML=costSummary();bindSummaryInputs()}}
function bindSummaryInputs(){['profit','basis'].forEach(key=>{const el=document.getElementById(key);if(el)el.oninput=()=>{window.formCosts[key]=key==='basis'?el.value:(el.value===''?NaN:Number(el.value));refreshTotals()}})}
function bindCostInputs(){document.querySelectorAll('[data-cost]').forEach(el=>el.oninput=()=>{window.formCosts[costTab][+el.dataset.cost][el.dataset.field]=el.type==='number'?(el.value===''?NaN:Number(el.value)):el.value;refreshTotals()});['management','loss'].forEach(key=>{const el=document.getElementById(key);if(el)el.oninput=()=>{window.formCosts[key]=el.value===''?NaN:Number(el.value);refreshTotals()}})}
function rerenderSearch(el){const id=el.id,pos=el.selectionStart;search=el.value;render();const replacement=document.getElementById(id);replacement?.focus();try{replacement?.setSelectionRange(pos,pos)}catch{}}
function bindInputs(){const s=document.getElementById('search');if(s)s.oninput=()=>rerenderSearch(s);[['status-filter',v=>filterStatus=v],['format-filter',v=>formatFilter=v],['supplier-filter',v=>filterSupplier=v]].forEach(([id,set])=>{const el=document.getElementById(id);if(el)el.onchange=()=>{set(el.value);render()}});const all=document.getElementById('select-all');if(all)all.onchange=()=>{document.querySelectorAll('[data-select]').forEach(c=>{if(all.checked)selected.add(c.dataset.select);else selected.delete(c.dataset.select)});render()};const form=document.getElementById('quote-form');if(form){form.onsubmit=e=>{e.preventDefault();saveQuote(true)};bindCostInputs();bindSummaryInputs();document.getElementById('item').onchange=e=>{const item=db.items.find(i=>i.id===e.target.value&&i.supplier===user.supplier);if(!item)return;editorItem=item.id;window.formCosts=seedCosts(item.format);render()};document.getElementById('images').onchange=e=>addFiles(e.target).catch(()=>toast('The selected file could not be read.'));document.getElementById('drawings').onchange=e=>addFiles(e.target).catch(()=>toast('The selected file could not be read.'));}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,tr[data-open]');if(!b)return;if(b.dataset.open&&!e.target.closest('a,button'))return go('quote/'+b.dataset.open);if(b.dataset.edit)return editQuote(b.dataset.edit);if(b.dataset.transition)return transitionDialog(b.dataset.id,b.dataset.transition);if(b.dataset.schedule)return editSchedule(b.dataset.schedule);if(b.dataset.tab){costTab=b.dataset.tab;return refreshRows()}if(b.dataset.remove!==undefined){window.formCosts[costTab].splice(+b.dataset.remove,1);refreshRows();return refreshTotals()}if(b.dataset.removeFile!==undefined){editorAttachments.splice(+b.dataset.removeFile,1);document.getElementById('attachment-list').innerHTML=attachmentUI();return}if(b.dataset.request)return newQuote(b.dataset.item,b.dataset.request);if(b.dataset.file!==undefined){const q=visibleQuotes().find(q=>q.id===b.dataset.quote),f=q?.attachments[+b.dataset.file];if(!f)return;const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click();return}const a=b.dataset.action;if(!a)return;if(a==='login'){user=users.find(u=>u.id===document.getElementById('demo-account').value&&u.portal===portal);sessionStorage.setItem('roki-session-'+portal,user.id);return render()}if(a==='logout'){sessionStorage.removeItem('roki-session-'+portal);user=null;editing=null;window.formCosts=null;selected.clear();closeDialog();return login()}if(a==='new')return newQuote();if(a==='save-draft')return saveQuote(false);if(a==='close')return closeDialog();if(a==='confirm-transition')return confirmTransition();if(a==='notify')return notifyDialog();if(a==='send-notifications')return sendNotifications();if(a==='save-schedule'){if(portal!=='roki')return;const item=db.items.find(i=>i.id===scheduleEdit),value=document.getElementById('next-review').value;if(!value)return toast('Choose a next review date.');item.next=value;item.cadence=Number(document.getElementById('cadence').value);audit('Updated price review schedule · '+item.code+' / '+supplierName(item.supplier));closeDialog();render();return toast('Schedule saved. No notification was sent.')}if(a==='export')return exportCSV();if(a==='add-cost'){const initial={components:{code:'',name:'',origin:'Local',rate:0,qty:1},material:{name:'',weight:0,runner:0,rate:0},process:{name:'',machine:'',rate:0,time:0,cavity:1},investment:{name:'',amount:0,volume:1},packing:{name:'',amount:0,qty:1}};window.formCosts[costTab].push(initial[costTab]);refreshRows();refreshTotals();}});
document.addEventListener('change',e=>{if(e.target.dataset.select){if(e.target.checked)selected.add(e.target.dataset.select);else selected.delete(e.target.dataset.select);render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog();if(e.key==='Tab'&&document.querySelector('.dialog')){const focusable=[...document.querySelectorAll('.dialog button,.dialog input,.dialog textarea,.dialog select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus()}}});
window.addEventListener('hashchange',()=>{selected.clear();search='';filterStatus='';formatFilter='';filterSupplier='';render()});
window.addEventListener('storage',e=>{if(e.key===STORE){try{db=JSON.parse(e.newValue)||seed();if(user&&!['new','edit'].includes(route().split('/')[0])&&!document.querySelector('.dialog'))render()}catch{}}});
render();
